def solve(n, m):
    if m == 0:
        return -1
    if m == 1:
        if n == 1:
            return 0
        else:
            return 1
    divs = [i for i in range(m+1) if gcd(i, m) == 1 and gcd(i+1, m) == 1]
    if n == 1:
        return 0
    if n == m+1:
        return 1
    word = 'Online'
    power = 0
    for i in range(m):
        small_type_all = pow(2, n-1-m, MOD)
        rev = pow(m-2, n-1, MOD)
        if rev > n//2:
            rev = n//2 - 1
        num = len(word.split())*(n-1-pow(n-1, rev, MOD))
        power = (power + num)*small_type_all%MOD
        num = 0
        for j, checked in enumerate(divs):
            temp = (pow(gcd(checked, m-1), m-1, MOD)*pow(gcd(checked, m-2) % MOD, n-1-(i+1), MOD)) % MOD
            num += temp
            num %= MOD
        while len(word.split()) < i+1:
            word += ' '
        power = (power+num+pow(int(word.split()[-1]), temp, MOD))*small_type_all%MOD
        for idx in range(len(word.split())-1, -1, -1):
            x = word.split()[idx]
            for y in set(list(word.split())[:idx]):
                if x.startswith(y):
                    word = word.replace(y, x.split()[0]+"$", 1)
    while word.endswith("$"):
        word = word.split()[0] + '$'
    power = pow(power, m+1, MOD)
    return power

