import math

def find_set(n, k):
    if n < k:
        return "No"

    # Since we need to have a greatest common divisor (GCD) > 1, but not factorial, we can start from reducing down limits
    # Using Euclidean algorithm, n/2, n-1, n-3, 2n
    possible_elements = {2, 3, 4, n//2, n//2-1, n//2-3}
    for _ in range(1, k):
        new_elements = set()
        for x in possible_elements:
            for y in possible_elements:
                new_elements.add(x // (x // y if x // y > 1 else 2))
        if len(new_elements) >= k:
            return "Yes", len(new_elements), sorted(new_elements)
        possible_elements = new_elements

    return "No"

# Read input
