def max_laps(n: int, a: List[int], l: List[int]) -> List[int]:
    leaps = defaultdict(lambda: defaultdict(list))
    dp = [[-1] * 400001 for _ in range(400001)]
    consecutive_prefix_lengths = [0] * (n + 1)

    for i in range(n + 1):
        if a[i] == 0:
            continue
        consecutive_prefix_lengths[i] = consecutive_prefix_lengths[i - 1] + 1
        for j in range(i):
            if a[j] + consecutive_prefix_lengths[j] <= a[i] - consecutive_prefix_lengths[i] and leaps[j][a[j] + consecutive_prefix_lengths[j]] == []:
                leaps[j][a[j] + consecutive_prefix_lengths[j]] = [a[j], a[i] - consecutive_prefix_lengths[i]]
                dir = (a[i] - 0) // 2 * (a[i] - consecutive_prefix_lengths[i] + a[j]) // a[i]
                if a[i] - consecutive_prefix_lengths[i] < x:
                    dp[a[i] - consecutive_prefix_lengths[i]][a[i] - consecutive_prefix_lengths[i]] = \
                        [i, j, dir, 0, 0, dir + consecutive_prefix_lengths[i], x, x, x, x]
                elif a[0] < x:
                    dp[x*a[i] // (a[i] - consecutive_prefix_lengths[i])][x] = \
                        [i, j, (x*a[i])**2 // a[j], x*x//a[j], -(x*a[i])//a[j], x*x//a[j], x, x, x, x]
                dp[i][a[i] - consecutive_prefix_lengths[i]] = \
                    [i, j, 0, 0, 0, 0, x, a[j] + consecutive_prefix_lengths[j], 0, 0]

    ans = []
    for l in l:
        if dp[l[0]][l[1]][2] == l[2] and dp[l[0]][l[1]][2] < 0:
            l_min = l[0]
            l_max = x
            while l_min <= l_max:
                m = (l_min + l_max) // 2
                if l_max - m == m * m - dp[l_min][l[1]][3]:
                    ans.append(m)
                    break
                elif m < l_max:
                    l_min = m + 1
        else:
            ans.append(-1)

    return ans

