import itertools

class SuffixAutomaton:
    def __init__(self):
        self.start = None
        self.current = self.start

    def append(self, word):
        if not self.current:
            self.start = self.current = self.__class__()
            self.current.word = itertools.cycle(word)
        else:
            self.current.current.append(word)
            self.current = self.current.current

    def collapse(self):
        if not self.current:
            return

        if not self.current.current:
            self.current.next = self.current = None
            return

        count = 0
        last = self.current.current
        while last.totalized:
            last.totalized = False
            if last.next:
                last.value = max(last.value, last.next.value)
                last.next = next(last.next.current)
            count += 1
            last = last.current

        self.current.value = last.value + 1
        if count:
            totalized = itertools.accumulate(self.current.current, partial(next, self.current))
            for i in range(count):
                totalized.next = itertools.count().next
            if count == 1:
                self.current = None
            else:
                ind = next(totalized.current)
                last.next = next(self.current.ind_to_ind[ind] or last)
                for j in reversed(range(count)):
                    ind = self.current.ind_to_ind.pop(ind)
                    last.substring = itertools.takewhile(pred, totalized.iter[j:])
                    last.current = last.next
                    last = last.substring

    def query(self, w, i):
        if not self.current:
            return 0

        l = r = i
        if w:
            cnt = 1
            last = next(self.current.get(w))
            l = i + 1 - cnt
            r = i + 1
        cval = last.value
        v = 0
        for n in r:
            cval = max(cval, last.improper)
            v += cval-popcount(cval)
            last = next(last.get(w))
            if last.substring:
                v += next(last.substring)
            last = next(self.current.get(w))
            cval = max(cval, last.value)
        return v + (i * (i + 1) + cval) // 2

def popcount(n):
    return bin(n).count('1')

def next(it):
    try:
        return next(it)
    except StopIteration:
        raise ValueError

