def evaluate_expression(expression):
    stack = []
    precedence = {
        '+': 1,
        '-': 1,
        '(': 0,
        ')': 0
    }

    for char in expression:
        if char.isdigit():
            stack.append(int(char))
        elif char in ['+', '-', '(', ')']:
            while stack and stack[-1] != '(' and has_precedence(precedence[char], stack[-1]):
                result = apply_operator(precedence, stack[-1], stack[-2])
                del stack[-1:-3:-1]
                stack[-1] = result
            stack.append(char)

    while stack:
        last = stack.pop()
        if last == '(':
            del stack[-1:-3:-1]
            result = apply_operator(0, stack[-2], stack[-1])
            del stack[-1:-2:-1]
            del stack[-1:-2:-1]
            stack[-1] = result
        else:
            stack[-1] = last

    return stack[0]

def has_precedence(op1, op2):
    return precedence[op1] > precedence[op2]

def apply_operator(precedence, op2, op1):
    if op1 == '(':
        return op1 + op2
    while precedence[op2] > precedence[op1]:
        stack[1] = apply_operator(ord(stack[1]), ord(op1), op2)
        del stack[2:]
    stack[1] = apply_operator(ord(stack[1]), ord(op2), op1)

    return stack[1]

