def find_divisor_value(length, current_max):
    max_value = 0
    for i in range(bisect_left(divisors, current_max), len(divisors)):
        if current_max % divisors[i] == 0:
            max_value = divisors[i]
            break
    if max_value == 0:
        return -1
    return max_value

def find_possible_divisors(length):
    possible_divisors = []
    for i in range(len(divisors) - 1):
        current_max = divisors[i + 1] - divisors[i]
        if current_max > length:
            break
        divisors_value = find_divisor_value(length, current_max)
        if divisors_value == -1:
            break
        possible_divisors.append(divisors_value)
    if length % possible_divisors[-1] == 0:
        return possible_divisors
    for i in range(len(divisors)-2, -1, -1):
        new_value = possible_divisors[-1]
        while possible_divisors[-1] * new_value > length:
            possible_divisors.pop()
            new_value = possible_divisors[-1]
        if new_value % length == 0:
            return possible_divisors
    return []

def find_maximal_lap_length(length, required_lap_length):
    divisors = []
    for i in range(2, int(length ** 0.5) + 1):
        if length % i == 0:
            divisors.append(i)
            r = length // i
            if r != i:
                divisors.append(r)
    divisors = sorted(divisors)
    partial_values = []
    for i in range(len(divisors)):
        partial_values.append(find_possible_divisors(divisors[i]))
    result_value = -1
    for i in range(len(divisors)):
        for value in partial_values[i]:
            if value > result_value:
                result_value = value
            elif value < result_value:
