import sys

def find_set(n, k):
    if n < k:
        return "No"

    couple_pairs = 0
    candidates = set([x*2 for x in range(1, n//2+1) if (n//x) > k])
    candidates.discard(n)
    cand_len = len(candidates)

    if cand_len < k:
        return "No"

    couple_pairs = k*(k+1)//2

    for i in range(1, cand_len-k+1):
        if candidates[i] + candidates[i+k] >= n-1:
            couple_pairs -= max(0, couple_pairs - 2)

    if couple_pairs > n-k:
        return "Yes"

    i = 1
    total = 2

    while i < cand_len and total < n-k:
        total += candidates[i]
        i += 1

    ls = list(candidates)
    total += ls[i-1]

    if total == n-k:
        return str(total) + " " + " ".join(map(str, sorted(ls[:i])))

    diff = sum(candidates[:i]) - total 
    new_pos = i + (n-k) - total
    new_pos += diff
    return "Yes, " + str(new_pos) + " " + " ".join(map(str, candidates[new_pos::])) + " " + " ".join(map(str, candidates[:i]+candidates[i:new_pos]))

if __name__ == "__main__":
