To solve this problem, we will write a Python program that checks if the given arithmetic sequence can be transformed into another arithmetic sequence such that the decimal representation of the first element in the transformed sequence appears as a substring of the last \(18\) digits of \(F_{b + i \cdot e}\) for all \(0 \leq i < n\). We will iterate over possible values of \(b\) and \(e\) and check if the condition is satisfied. If found, we will print the values of \(b\) and \(e\).

```python
def fib(n):
    if n <= 1:
        return n
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

def check_condition(n, a, d, e):
    # Generate the decimal representation of F_{b + i \cdot e} for all i < n
    F = []
    for i in range(n):
        F.append(fib(a + i * d))

    # Check if any Fibonacci number's first digit is present in the 18th digit of the next Fibonacci number
    for i in range(n - 1):
        if str(F[i])[:18] in str(F[i + 1]):
            return True
    return False

def find_oracle_sequence(n, a, d):
    for b in range(2 ** 64):
        for e in range(2 ** 64):
            if check_condition(n, a, d, e):
                return b, e
    return -1

