from math import gcd
from collections import defaultdict
from typing import List, Dict, Tuple

def calculate_bfm(b: int) -> Tuple[int, int]:
    bfm = 1  # Initialize with 1 as lcm is always less than or equal to b
    factors = []
    while b > 1:
        prime = find_smallest_prime(b)
        factors.append((prime, b // prime))
        b = find_smallest_prime(b // prime)

    # Kaisha: An optimized approach to lcmm function, calculated by creating table
    table = defaultdict(int)
    for i, j in factors:
        lcm_val = max(i, j) * (i // gcd(i, j))
        table[lcm_val] += 1

    for i in range(1, b):
        lcm_multipliers = table[i]
        for weights in range(1, lcm_multipliers + 1):
            lcm = i * weights
            excluded, required = 0, lcm - 1
            powers_in_factors = defaultdict(int)
            for factor in factors:
                current_power = factor[1] // weights
                excluded += current_power
                powers_in_factors[current_power] += current_power
                required -= current_power

            for power, occurrences in powers_in_factors.items():
                excluded += occurrences
                required -= occurrences

            multiple = 1
            for factor in factors:
                if occurrences > 0:
                    multiple *= factor[0]
                else:
                    multiple *= factor[0] ** occurrences

            table[lcm] += multiple * bfm

    return bfm, factors

def find_smallest_prime(x: int) -> Tuple[int, int]:
    while x > 1:
        y = x
        for j in range(2, x):
            if x % j == 0:
                x //= j
                y = j
                break
        yield y, x

def prime_multiplication_factor(n: int) -> int:
    p, e = 1, 1
    r = defaultdict(int)
    while e > 0:
        for factor in find_smallest_prime(p):
            while e >= factor[1]:
                e -= factor[1]
                r[factor[0]] += factor[1]
            if not r[factor[0]]:
                break
        p *= factor[0]
        e = r[factor[0]]
    return p

def modular_exponentiation(a: int, b: int, m: int) -> int:
    result = 1
    while b:
        if b & 1:
            result = result * a % m
        a = (a * a) % m
        b >>= 1
    return result

