from collections import deque

def evaluate_expression(expression: str) -> int:
    stack = deque()
    num_stack = deque()

    for char in expression:
        if char.isdigit():
            num_str = char
            while expression and expression[0].isnumeric():
                num_str += expression.popleft()
            num_stack.append(int(num_str))
        elif char in ["-", "+"]:
            while stack and stack[-1] in ["-", "+"]:
                result = stack.pop()
                num1 = num_stack.pop()
                num2 = num_stack.pop()
                stack.append(result + num1 - num2 if char == '+' else result - num1 + num2)
        else:
            stack.append(char)

    result = 0
    while stack:
        result = stack.pop() + num_stack.pop() - num_stack.pop()

    return result

